    // 비압축 포맷의 총 바이트 수. bitsPerPixel 은 8 의 배수(8, 16, 24, 32, 64 ...).
    // 각 레벨의 바이트 = 가로 * 세로 * (bitsPerPixel / 8), 모든 레벨을 더한다.
    public static long UncompressedBytes(int width, int height, int bitsPerPixel, bool mipmaps)
    {
        throw new NotImplementedException();
    }

    // ASTC 처럼 "블록 하나 = 128비트(16바이트)" 인 블록 압축 포맷의 총 바이트 수.
    // 각 레벨의 블록 수 = ceil(가로 / blockWidth) * ceil(세로 / blockHeight).
    public static long AstcBytes(int width, int height, int blockWidth, int blockHeight, bool mipmaps)
