        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string U(int w, int h, int bpp, bool mip, long exp)
    {
        long got = TextureMemory.UncompressedBytes(w, h, bpp, mip);
        return got == exp ? null : "UncompressedBytes(" + w + ", " + h + ", " + bpp + ", " + mip + "): 기대 " + exp + ", 결과 " + got;
    }

    static string A(int w, int h, int bw, int bh, bool mip, long exp)
    {
        long got = TextureMemory.AstcBytes(w, h, bw, bh, mip);
        return got == exp ? null : "AstcBytes(" + w + ", " + h + ", " + bw + "x" + bh + ", " + mip + "): 기대 " + exp + ", 결과 " + got;
    }

    static string M(int w, int h, bool mip, int exp)
    {
        int got = TextureMemory.MipCount(w, h, mip);
        return got == exp ? null : "MipCount(" + w + ", " + h + ", " + mip + "): 기대 " + exp + ", 결과 " + got;
    }

    static bool Throws(System.Action a)
    {
        try { a(); } catch (System.ArgumentOutOfRangeException) { return true; } catch (System.Exception) { return false; }
        return false;
    }

    // 참조 구현: 레벨 k 의 한 변 = max(1, size >> k)
    static long RefBytes(int w, int h, int bw, int bh, long unit, bool mip)
    {
        long total = 0;
        for (int k = 0; ; k++)
        {
            long lw = System.Math.Max(1, w >> k), lh = System.Math.Max(1, h >> k);
            total += ((lw + bw - 1) / bw) * ((lh + bh - 1) / bh) * unit;
            if (!mip || (lw == 1 && lh == 1)) break;
        }
        return total;
    }

