        Run("astc-blocks", () =>
        {
            string e = A(1024, 1024, 4, 4, false, 1048576L) ?? A(1024, 1024, 6, 6, false, 467856L)
                ?? A(100, 50, 8, 8, false, 1456L) ?? A(25, 25, 10, 5, false, 240L) ?? A(1, 1, 12, 12, false, 16L)
                ?? A(8, 8, 4, 4, true, 112L) ?? A(1920, 1080, 6, 6, true, 1229520L);
