            if (System.Math.Abs(b105 - 2.56) > 1e-9) return "AstcBitsPerPixel(10, 5): 기대 2.56, 결과 " + b105;
            return null;
        });

        Run("large-no-overflow", () =>
            U(16384, 16384, 32, false, 1073741824L) ?? U(16384, 16384, 32, true, 1431655764L)
            ?? U(16384, 8192, 64, false, 1073741824L) ?? A(16384, 16384, 4, 4, true, 357913968L)
            ?? U(16384, 16384, 64, false, 2147483648L) ?? U(16384, 16384, 64, true, 2863311528L)
            ?? U(32768, 32768, 32, false, 4294967296L) ?? A(65536, 65536, 4, 4, false, 4294967296L));

        Run("invalid-arguments", () =>
        {
            if (!Throws(() => TextureMemory.UncompressedBytes(0, 16, 32, true))) return "width 0: ArgumentOutOfRangeException 이 나와야 함";
            if (!Throws(() => TextureMemory.UncompressedBytes(16, -1, 32, false))) return "height -1: ArgumentOutOfRangeException 이 나와야 함";
            if (!Throws(() => TextureMemory.UncompressedBytes(16, 16, 0, false))) return "bitsPerPixel 0: ArgumentOutOfRangeException 이 나와야 함";
            if (!Throws(() => TextureMemory.UncompressedBytes(16, 16, 12, false))) return "bitsPerPixel 12(8의 배수 아님): ArgumentOutOfRangeException 이 나와야 함";
            if (!Throws(() => TextureMemory.AstcBytes(16, 16, 0, 4, false))) return "blockWidth 0: ArgumentOutOfRangeException 이 나와야 함";
            if (!Throws(() => TextureMemory.MipCount(0, 0, true))) return "MipCount(0, 0): ArgumentOutOfRangeException 이 나와야 함";
            if (!Throws(() => TextureMemory.MipCount(4, -1, false))) return "MipCount(4, -1): ArgumentOutOfRangeException 이 나와야 함";
            if (!Throws(() => TextureMemory.UncompressedBytes(16, 16, -8, false))) return "bitsPerPixel -8: ArgumentOutOfRangeException 이 나와야 함";
            if (!Throws(() => TextureMemory.AstcBytes(16, 16, 4, -1, true))) return "blockHeight -1: ArgumentOutOfRangeException 이 나와야 함";
            if (!Throws(() => TextureMemory.AstcBytes(0, 16, 4, 4, false))) return "AstcBytes width 0: ArgumentOutOfRangeException 이 나와야 함";
            if (!Throws(() => TextureMemory.AstcBitsPerPixel(0, 4))) return "AstcBitsPerPixel(0, 4): ArgumentOutOfRangeException 이 나와야 함";
            if (!Throws(() => TextureMemory.AstcBitsPerPixel(4, -2))) return "AstcBitsPerPixel(4, -2): ArgumentOutOfRangeException 이 나와야 함";
            return null;
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            int[] bpps = { 8, 16, 24, 32, 64 };
            int[] blocks = { 4, 5, 6, 8, 10, 12 };
            for (int i = 0; i < 3000; i++)
            {
                int w = rng.Next(100) < 30 ? 1 << rng.Next(0, 13) : rng.Next(1, 5000);
                int h = rng.Next(100) < 30 ? 1 << rng.Next(0, 13) : rng.Next(1, 5000);
                bool mip = rng.Next(2) == 0;
                int bpp = bpps[rng.Next(bpps.Length)];
                string e = U(w, h, bpp, mip, RefBytes(w, h, 1, 1, bpp / 8, mip));
                if (e != null) return e;
                int bw = blocks[rng.Next(blocks.Length)], bh = blocks[rng.Next(blocks.Length)];
                e = A(w, h, bw, bh, mip, RefBytes(w, h, bw, bh, 16, mip));
                if (e != null) return e;
            }
            return null;
        });
    }
}

