public static class __Judge
{
    const float Eps = 1e-4f;

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static System.Numerics.Vector3 V(float x, float y, float z) { return new System.Numerics.Vector3(x, y, z); }

    static bool Near(float got, double exp) { return !float.IsNaN(got) && System.Math.Abs(got - exp) <= Eps; }

    static string D(System.Numerics.Vector3 n, System.Numerics.Vector3 l, double exp)
    {
        float got = Lighting.Diffuse(n, l);
        return Near(got, exp) ? null : "Diffuse(N=" + n + ", L=" + l + "): 기대 " + exp.ToString("0.#####") + ", 결과 " + got;
    }

    static string S(System.Numerics.Vector3 n, System.Numerics.Vector3 l, System.Numerics.Vector3 v, float sh, double exp)
    {
        float got = Lighting.Specular(n, l, v, sh);
        return Near(got, exp) ? null : "Specular(N=" + n + ", L=" + l + ", V=" + v + ", shininess=" + sh + "): 기대 " + exp.ToString("0.#####") + ", 결과 " + got;
    }

    static string C(System.Numerics.Vector3 got, double r, double g, double b, string what)
    {
        return Near(got.X, r) && Near(got.Y, g) && Near(got.Z, b) ? null
            : what + ": 기대 (" + r.ToString("0.#####") + ", " + g.ToString("0.#####") + ", " + b.ToString("0.#####") + "), 결과 " + got;
    }

    // double 참조 구현
    static bool Norm(double[] a, out double[] r)
    {
        double len = System.Math.Sqrt(a[0] * a[0] + a[1] * a[1] + a[2] * a[2]);
        r = len > 0 ? new[] { a[0] / len, a[1] / len, a[2] / len } : null;
        return len > 0;
    }
    static double Dot(double[] a, double[] b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }
    static double[] A(System.Numerics.Vector3 v) { return new double[] { v.X, v.Y, v.Z }; }
    static double RefDiffuse(System.Numerics.Vector3 n, System.Numerics.Vector3 l)
    {
        if (!Norm(A(n), out var nn) || !Norm(A(l), out var ll)) return 0;
        return System.Math.Min(1.0, System.Math.Max(0.0, Dot(nn, ll)));
    }
    static double RefSpecular(System.Numerics.Vector3 n, System.Numerics.Vector3 l, System.Numerics.Vector3 v, double sh)
    {
        if (!Norm(A(n), out var nn) || !Norm(A(l), out var ll) || !Norm(A(v), out var vv)) return 0;
        if (Dot(nn, ll) <= 0) return 0;
        if (!Norm(new[] { ll[0] + vv[0], ll[1] + vv[1], ll[2] + vv[2] }, out var hh)) return 0;
        return System.Math.Pow(System.Math.Min(1.0, System.Math.Max(0.0, Dot(nn, hh))), sh);
    }

    public static void Main()
    {
        Run("saturate", () =>
        {
            float[] xs = { -2f, 0f, 0.25f, 1f, 3.5f };
            float[] es = { 0f, 0f, 0.25f, 1f, 1f };
            for (int i = 0; i < xs.Length; i++)
                if (!Near(Lighting.Saturate(xs[i]), es[i])) return "Saturate(" + xs[i] + "): 기대 " + es[i] + ", 결과 " + Lighting.Saturate(xs[i]);
            return null;
        });

        Run("diffuse-basic", () =>
            D(V(0, 1, 0), V(0, 1, 0), 1.0) ?? D(V(0, 1, 0), V(1, 0, 0), 0.0) ?? D(V(0, 1, 0), V(0, -1, 0), 0.0)
            ?? D(V(0, 1, 0), V(0.6f, 0.8f, 0), 0.8) ?? D(V(0, 1, 0), V(0.6f, -0.8f, 0), 0.0));

        Run("diffuse-unnormalized", () =>
            D(V(0, 5, 0), V(3, 4, 0), 0.8) ?? D(V(0, 0, 2), V(0, 3, 3), 0.70710678) ?? D(V(0, 0.01f, 0), V(0, 1000, 0), 1.0)
            ?? D(V(2, 2, 0), V(10, 0, 0), 0.70710678));

        Run("specular-half-vector", () =>
            S(V(0, 1, 0), V(0, 1, 0), V(0, 1, 0), 16f, 1.0) ?? S(V(0, 1, 0), V(0, 1, 0), V(1, 0, 0), 2f, 0.5)
            ?? S(V(0, 1, 0), V(0, 1, 0), V(1, 0, 0), 8f, 0.0625) ?? S(V(0, 1, 0), V(1, 1, 0), V(1, 1, 0), 4f, 0.25));

        Run("specular-unnormalized", () =>
            S(V(0, 1, 0), V(0, 10, 0), V(0.5f, 0, 0), 2f, 0.5) ?? S(V(0, 2, 0), V(2, 2, 0), V(-3, 3, 0), 32f, 1.0)
            ?? S(V(0, 3, 0), V(0, 0.1f, 0), V(7, 0, 0), 8f, 0.0625));

        Run("specular-backface", () =>
            S(V(0, 1, 0), V(1, -0.1f, 0), V(-1, 1, 0), 4f, 0.0) ?? S(V(0, 1, 0), V(0, -1, 0), V(1, 1, 0), 2f, 0.0)
            ?? S(V(0, 1, 0), V(1, 0, 0), V(0, 1, 0), 1f, 0.0));

        Run("degenerate-vectors", () =>
            D(V(0, 0, 0), V(0, 1, 0), 0.0) ?? D(V(0, 1, 0), V(0, 0, 0), 0.0)
            ?? S(V(0, 1, 0), V(0, 1, 0), V(0, 0, 0), 4f, 0.0) ?? S(V(0, 0, 0), V(0, 1, 0), V(0, 1, 0), 4f, 0.0)
            ?? S(V(0, 1, 0), V(0, 2, 0), V(0, -3, 0), 4f, 0.0)
            ?? C(Lighting.Shade(V(0, 0, 0), V(0, 1, 0), V(0, 1, 0), V(1, 1, 1), V(1, 1, 1), V(1, 1, 1), 4f), 0, 0, 0, "Shade(N = 0 벡터)"));

        Run("shade-color", () =>
            C(Lighting.Shade(V(0, 1, 0), V(0, 10, 0), V(0.5f, 0, 0), V(1, 0.5f, 0.25f), V(1, 1, 1), V(2, 1, 0.5f), 2f), 3.0, 1.0, 0.375, "Shade #1")
            ?? C(Lighting.Shade(V(0, 5, 0), V(3, 4, 0), V(3, 4, 0), V(0.5f, 0.5f, 0.5f), V(0.25f, 0.25f, 0.25f), V(1, 1, 1), 2f), 0.56, 0.56, 0.56, "Shade #2")
            ?? C(Lighting.Shade(V(0, 1, 0), V(0, -1, 0), V(0, 1, 0), V(1, 1, 1), V(1, 1, 1), V(1, 1, 1), 2f), 0, 0, 0, "Shade #3 (뒤에서 오는 빛)"));

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(9001);
            for (int i = 0; i < 4000; i++)
            {
                var n = V(rng.Next(-40, 41) / 8f, rng.Next(-40, 41) / 8f, rng.Next(-40, 41) / 8f);
                var l = V(rng.Next(-40, 41) / 8f, rng.Next(-40, 41) / 8f, rng.Next(-40, 41) / 8f);
                var v = V(rng.Next(-40, 41) / 8f, rng.Next(-40, 41) / 8f, rng.Next(-40, 41) / 8f);
                float sh = 1 + rng.Next(0, 24);
                // 판정 경계(dot(N, L) = 0 근처, L + V = 0 근처)는 float 오차로 결과가 갈릴 수 있어 건너뛴다.
                if (!Norm(A(n), out var nn) || !Norm(A(l), out var ll) || !Norm(A(v), out var vv)) continue;
                if (System.Math.Abs(Dot(nn, ll)) < 1e-3) continue;
                double sx = ll[0] + vv[0], sy = ll[1] + vv[1], sz = ll[2] + vv[2];
                if (sx * sx + sy * sy + sz * sz < 1e-4) continue;
                string e = D(n, l, RefDiffuse(n, l)) ?? S(n, l, v, sh, RefSpecular(n, l, v, sh));
                if (e != null) return e;
            }
            return null;
        });
    }
}

