using System;

public static class ColorSpace
{
    public static float SrgbToLinear(float srgb)
    {
        float c = Clamp01(srgb);
        // 어두운 구간은 직선, 나머지는 지수 2.4 의 거듭제곱 곡선이다.
        if (c <= 0.04045f) return c / 12.92f;
        return MathF.Pow((c + 0.055f) / 1.055f, 2.4f);
    }

    public static float LinearToSrgb(float linear)
    {
        float c = Clamp01(linear);
        if (c <= 0.0031308f) return 12.92f * c;
        return 1.055f * MathF.Pow(c, 1f / 2.4f) - 0.055f;
    }

    public static byte LerpSrgb8(byte a, byte b, float t)
    {
        // 섞는 계산은 빛의 양에 비례하는 선형 값으로 한다.
        float la = SrgbToLinear(a / 255f);
        float lb = SrgbToLinear(b / 255f);
        float mixed = la + (lb - la) * Clamp01(t);
        // 결과를 다시 sRGB 로 인코딩한 뒤 8비트로 반올림한다.
        return (byte)MathF.Floor(LinearToSrgb(mixed) * 255f + 0.5f);
    }

    private static float Clamp01(float x)
    {
        if (x < 0f) return 0f;
        if (x > 1f) return 1f;
        return x;
    }
}

