            ?? S(Row4, 4, 1, -2.0, 0.5, WrapMode.Clamp, 0.0) ?? S(Row4, 4, 1, 3.5, 7.0, WrapMode.Clamp, 3.0)
            ?? S(Grid22, 2, 2, 0.0, 0.0, WrapMode.Clamp, 0.0) ?? S(Grid22, 2, 2, 1.0, 1.0, WrapMode.Clamp, 5.0)
            ?? S(Grid22, 2, 2, 0.0, 1.0, WrapMode.Clamp, 2.0) ?? S(Grid22, 2, 2, 0.5, 1.0, WrapMode.Clamp, 3.5));

        Run("repeat-seam", () =>
            S(Row4, 4, 1, 0.0, 0.5, WrapMode.Repeat, 1.5) ?? S(Row4, 4, 1, 1.0, 0.5, WrapMode.Repeat, 1.5)
