            ?? S(Row4, 4, 1, 1.125, 0.5, WrapMode.Repeat, 0.0) ?? S(Row4, 4, 1, 2.625, 0.5, WrapMode.Repeat, 2.0)
            ?? S(Grid22, 2, 2, 0.0, 0.0, WrapMode.Repeat, 2.0) ?? S(Grid22, 2, 2, 0.25, 0.0, WrapMode.Repeat, 1.0));

        Run("negative-uv-repeat", () =>
