            ?? S(Row4, 4, 1, -0.25, 0.5, WrapMode.Repeat, 2.5) ?? S(Row4, 4, 1, -3.125, -2.5, WrapMode.Repeat, 3.0)
            ?? S(Row4, 4, 1, -0.0625, 0.5, WrapMode.Repeat, 2.25)
