    static int RefWrap(long i, int size, WrapMode m)
    {
        if (m == WrapMode.Repeat) return (int)(((i % size) + size) % size);
        return (int)System.Math.Max(0, System.Math.Min(size - 1, i));
    }
    static double RefPoint(double[,] g, int w, int h, double u, double v, WrapMode m)
    {
        return g[RefWrap((long)System.Math.Floor(u * w), w, m), RefWrap((long)System.Math.Floor(v * h), h, m)];
    }
    static double RefBilinear(double[,] g, int w, int h, double u, double v, WrapMode m)
