                // 바이리니어: 1/64 단위 좌표. 포인트: 텍셀 경계에 걸리지 않도록 홀수/128 좌표.
                double u = rng.Next(-128, 193) / 64.0, v = rng.Next(-128, 193) / 64.0;
                double pu = (2 * rng.Next(-128, 192) + 1) / 128.0, pv = (2 * rng.Next(-128, 192) + 1) / 128.0;
                string e = B(t, u, v, m, RefBilinear(grid, w, h, u, v, m)) ?? P(t, pu, pv, m, RefPoint(grid, w, h, pu, pv, m));
                if (e != null) return e;
            }
            return null;
        });
    }
}

