using System;
using System.Numerics;

// 규약 (문제 본문과 같다)
// - System.Numerics 는 벡터를 행으로 본다: v' = v * M. 변환은 왼쪽 행렬부터 차례로 적용된다.
// - projection 은 Matrix4x4.CreatePerspectiveFieldOfView 가 만든 행렬이다.
//   카메라는 뷰 공간의 -Z 를 보고, 클립 공간에서 보이는 범위는 -w <= x, y <= w, 0 <= z <= w.
// - 화면 좌표: 원점은 뷰포트의 왼쪽 위, x 는 오른쪽, y 는 아래쪽으로 증가. z 는 깊이 0(near) ~ 1(far).
public static class Projection
{
    public static Vector4 LocalToClip(Vector3 localPosition, Matrix4x4 model, Matrix4x4 view, Matrix4x4 projection)
    {
        // 행 벡터 규약이므로 모델 -> 뷰 -> 투영 순서로 왼쪽부터 곱한다. 위치이므로 w = 1.
        Matrix4x4 mvp = model * view * projection;
        return Vector4.Transform(new Vector4(localPosition, 1f), mvp);
    }

    public static bool IsInsideClipVolume(Vector4 clip)
    {
        // w <= 0 이면 카메라가 있는 평면 위이거나 그 뒤쪽이다. 나누기 전에 걸러야 한다.
        if (!(clip.W > 0f)) return false;
        return clip.X >= -clip.W && clip.X <= clip.W
            && clip.Y >= -clip.W && clip.Y <= clip.W
            && clip.Z >= 0f && clip.Z <= clip.W;
    }

    public static Vector3 ClipToNdc(Vector4 clip)
    {
        // 원근 나눗셈: 멀수록 w 가 커서 x, y 가 화면 중심 쪽으로 모인다.
        float invW = 1f / clip.W;
        return new Vector3(clip.X * invW, clip.Y * invW, clip.Z * invW);
    }

    public static Vector3 NdcToScreen(Vector3 ndc, float viewportWidth, float viewportHeight)
    {
        // NDC 의 y 는 위가 +1 이고 화면의 y 는 아래로 증가하므로 뒤집는다.
        float x = (ndc.X + 1f) * 0.5f * viewportWidth;
        float y = (1f - ndc.Y) * 0.5f * viewportHeight;
        return new Vector3(x, y, ndc.Z);
    }

    public static bool TryProject(Vector3 localPosition, Matrix4x4 model, Matrix4x4 view, Matrix4x4 projection,
                                  float viewportWidth, float viewportHeight, out Vector3 screen)
    {
        Vector4 clip = LocalToClip(localPosition, model, view, projection);
        if (!IsInsideClipVolume(clip))
        {
            screen = default;
            return false;
        }

        screen = NdcToScreen(ClipToNdc(clip), viewportWidth, viewportHeight);
        return true;
    }
}

