using System;
using System.Numerics;

// 규약 (문제 본문과 같다)
// - 평면은 Normal · p + D = 0 이고, Normal 은 절두체 "안쪽"을 가리킨다.
// - Normal 의 길이는 1 이 아닐 수 있다(0 은 아니다).
// - 구가 평면에 걸치거나 닿기만 해도 보이는 것으로 본다.
public static class FrustumCulling
{
    public static float SignedDistance(Plane plane, Vector3 point)
    {
        // 평면 식에 점을 넣은 값을 노멀의 길이로 나눠야 실제 거리가 된다.
        float value = Vector3.Dot(plane.Normal, point) + plane.D;
        return value / plane.Normal.Length();
    }

    public static bool IsSphereVisible(Plane[] planes, Vector3 center, float radius)
    {
        for (int i = 0; i < planes.Length; i++)
        {
            // 중심이 어느 한 평면의 바깥쪽으로 반지름보다 더 나가 있으면 구 전체가 그 평면 밖이다.
            if (SignedDistance(planes[i], center) < -radius) return false;
        }

        return true;
    }
}

