using System;

// 규약
// - distance 는 카메라가 보는 방향으로 잰 거리(뷰 공간 깊이)이고 near <= distance <= far 다.
// - 깊이 값은 near 에서 0, far 에서 1 이다 (Direct3D 식 0..1 범위, 뒤집지 않은 Z).
//   System.Numerics 의 Matrix4x4.CreatePerspectiveFieldOfView 로 투영한 뒤 z / w 를 구한 값과 같다.
public static class DepthMath
{
    // 거리 -> 깊이 값(0..1).  depth = far * (distance - near) / (distance * (far - near))
    public static double DistanceToDepth(double distance, double near, double far)
    {
        return far * (distance - near) / (distance * (far - near));
    }

    // 깊이 값(0..1) -> 거리.  위 식을 distance 에 대해 푼 것.
    public static double DepthToDistance(double depth, double near, double far)
    {
        return near * far / (far - depth * (far - near));
    }

    // 깊이 값(0..1) 을 bits 비트 정수 깊이 버퍼에 저장되는 값으로 바꾼다: round(depth * (2^bits - 1))
    public static long QuantizeDepth(double depth, int bits)
    {
        double clamped = Math.Min(1.0, Math.Max(0.0, depth));
        long maxValue = (1L << bits) - 1;
        return (long)Math.Round(clamped * maxValue, MidpointRounding.AwayFromZero);
    }
}

