using System;
using System.Numerics;

// 규약
// - 행 벡터 규약: 월드 위치 = Vector3.Transform(오브젝트 위치, model).
// - model 은 확대/축소(축마다 다를 수 있고 음수일 수도 있다), 회전, 이동을 합친 행렬이며 역행렬이 있다.
// - "노멀"을 돌려주는 함수는 모두 길이 1 인 벡터를 돌려준다.
// - 디퓨즈 값은 max(0, N · L) 이고, N 과 L 은 둘 다 월드 공간의 단위 벡터다.
public static class NormalShading
{
    public static Vector3 InterpolateNormal(Vector3 n0, Vector3 n1, Vector3 n2, float b0, float b1, float b2)
    {
        // [수정 1] 단위 벡터들의 가중평균은 길이가 1 보다 짧아진다. 보간한 뒤 다시 정규화한다.
        Vector3 n = n0 * b0 + n1 * b1 + n2 * b2;
        return Vector3.Normalize(n);
    }

    public static Vector3 ObjectToWorldNormal(Vector3 normalObject, Matrix4x4 model)
    {
        // [수정 2] 노멀은 표면에 수직이어야 하므로 model 이 아니라 model 의 역전치 행렬로 옮긴다.
        // 축마다 배율이 다르면 model 로 옮긴 노멀은 더 이상 표면에 수직이 아니다.
        Matrix4x4 inverse;
        if (!Matrix4x4.Invert(model, out inverse)) throw new ArgumentException("model 의 역행렬이 없다", nameof(model));
        Vector3 n = Vector3.TransformNormal(normalObject, Matrix4x4.Transpose(inverse));
        return Vector3.Normalize(n);
    }

    public static float PointLightDiffuse(Vector3 positionObject, Vector3 normalObject, Matrix4x4 model, Vector3 lightPositionWorld)
    {
        Vector3 n = ObjectToWorldNormal(normalObject, model);
        // [수정 3] 광원 위치는 월드 공간이므로 표면 위치도 월드 공간으로 옮긴 뒤 뺀다.
        Vector3 positionWorld = Vector3.Transform(positionObject, model);
        Vector3 toLight = Vector3.Normalize(lightPositionWorld - positionWorld);
        return MathF.Max(0f, Vector3.Dot(n, toLight));
    }
}

