public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string F(double v) { return v.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture); }
    static string S(System.Numerics.Vector3 v) { return "(" + F(v.X) + ", " + F(v.Y) + ", " + F(v.Z) + ")"; }
    static System.Numerics.Vector3 V(double x, double y, double z) { return new System.Numerics.Vector3((float)x, (float)y, (float)z); }
    static bool Near(double got, double exp, double eps) { return !double.IsNaN(got) && System.Math.Abs(got - exp) <= eps; }

    static string Vec(string what, System.Numerics.Vector3 got, double x, double y, double z, double eps)
    {
        return Near(got.X, x, eps) && Near(got.Y, y, eps) && Near(got.Z, z, eps) ? null : what + ": 기대 (" + F(x) + ", " + F(y) + ", " + F(z) + "), 결과 " + S(got);
    }
    static string Num(string what, double got, double exp, double eps)
    {
        return Near(got, exp, eps) ? null : what + ": 기대 " + F(exp) + ", 결과 " + F(got);
    }

    static System.Numerics.Matrix4x4 Scale(double x, double y, double z) { return System.Numerics.Matrix4x4.CreateScale((float)x, (float)y, (float)z); }
    static System.Numerics.Matrix4x4 Move(double x, double y, double z) { return System.Numerics.Matrix4x4.CreateTranslation((float)x, (float)y, (float)z); }

    // 참조 (double): 방향 d 를 행 벡터 규약으로 옮긴다 (이동 제외)
    static double[] Dir(double[] d, System.Numerics.Matrix4x4 m)
    {
        return new double[] { d[0] * m.M11 + d[1] * m.M21 + d[2] * m.M31, d[0] * m.M12 + d[1] * m.M22 + d[2] * m.M32, d[0] * m.M13 + d[1] * m.M23 + d[2] * m.M33 };
    }
    static double[] Cross(double[] a, double[] b) { return new double[] { a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0] }; }
    static double Dot(double[] a, double[] b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }
    static double[] Unit(double[] a) { double l = System.Math.Sqrt(Dot(a, a)); return new double[] { a[0] / l, a[1] / l, a[2] / l }; }
    // 참조 노멀: 노멀에 수직인 접선 두 개를 model 로 옮긴 뒤 외적한다. 역전치를 쓰지 않는 독립적인 계산이다.
    static double[] RefNormal(double[] n, System.Numerics.Matrix4x4 m)
    {
        double[] helper = System.Math.Abs(n[0]) < 0.6 ? new double[] { 1, 0, 0 } : new double[] { 0, 1, 0 };
        double[] t1 = Unit(Cross(n, helper)), t2 = Cross(n, t1); // t1 x t2 = n
        double[] c = Cross(Dir(t1, m), Dir(t2, m));
        double det = Dot(Cross(Dir(new double[] { 1, 0, 0 }, m), Dir(new double[] { 0, 1, 0 }, m)), Dir(new double[] { 0, 0, 1 }, m));
        double[] u = Unit(c);
        return det < 0 ? new double[] { -u[0], -u[1], -u[2] } : u;
    }
    static double RefDiffuse(double[] p, double[] n, System.Numerics.Matrix4x4 m, double[] light)
    {
        double[] d = Dir(p, m);
        double[] w = { d[0] + m.M41, d[1] + m.M42, d[2] + m.M43 };
        double[] l = Unit(new double[] { light[0] - w[0], light[1] - w[1], light[2] - w[2] });
        return System.Math.Max(0.0, Dot(RefNormal(n, m), l));
    }

    public static void Main()
    {
        double h = System.Math.Sqrt(0.5);

        Run("interpolate-unit-length", () =>
        {
            var x = V(1, 0, 0); var y = V(0, 1, 0); var z = V(0, 0, 1);
            double t = 1 / System.Math.Sqrt(3.0);
            return Vec("InterpolateNormal(X, Y, Z, 0.5, 0.5, 0)", NormalShading.InterpolateNormal(x, y, z, 0.5f, 0.5f, 0f), h, h, 0, 1e-4)
                ?? Vec("InterpolateNormal(X, Y, Z, 1/3, 1/3, 1/3)", NormalShading.InterpolateNormal(x, y, z, 1f / 3f, 1f / 3f, 1f / 3f), t, t, t, 1e-4)
                ?? Vec("InterpolateNormal(X, Y, Z, 0.25, 0, 0.75)", NormalShading.InterpolateNormal(x, y, z, 0.25f, 0f, 0.75f), 0.316228, 0, 0.948683, 1e-4)
                ?? Vec("InterpolateNormal(X, Y, Z, 0, 1, 0) [정점 위]", NormalShading.InterpolateNormal(x, y, z, 0f, 1f, 0f), 0, 1, 0, 1e-4)
                ?? Vec("InterpolateNormal(Y, Y, Y, 0.2, 0.3, 0.5) [평평한 면]", NormalShading.InterpolateNormal(y, y, y, 0.2f, 0.3f, 0.5f), 0, 1, 0, 1e-4);
        });

        Run("normal-rigid-transform", () =>
        {
            // 회전과 이동만 있는 model: 노멀은 회전만 따라간다
            var rotZ = System.Numerics.Matrix4x4.CreateRotationZ((float)(System.Math.PI / 2));
            return Vec("ObjectToWorldNormal((0, 1, 0), 단위행렬)", NormalShading.ObjectToWorldNormal(V(0, 1, 0), System.Numerics.Matrix4x4.Identity), 0, 1, 0, 1e-4)
                ?? Vec("ObjectToWorldNormal((1, 0, 0), Z축 90도 회전)", NormalShading.ObjectToWorldNormal(V(1, 0, 0), rotZ), 0, 1, 0, 1e-4)
                ?? Vec("ObjectToWorldNormal((0, 1, 0), Z축 90도 회전 후 (5, 6, 7) 이동)", NormalShading.ObjectToWorldNormal(V(0, 1, 0), rotZ * Move(5, 6, 7)), -1, 0, 0, 1e-4)
                ?? Vec("ObjectToWorldNormal((0.6, 0.8, 0), (100, -50, 3) 이동)", NormalShading.ObjectToWorldNormal(V(0.6, 0.8, 0), Move(100, -50, 3)), 0.6, 0.8, 0, 1e-4)
                ?? Vec("ObjectToWorldNormal((0.6, 0.8, 0), 3배 균등 확대)", NormalShading.ObjectToWorldNormal(V(0.6, 0.8, 0), Scale(3, 3, 3)), 0.6, 0.8, 0, 1e-4);
        });

        Run("normal-nonuniform-scale", () =>
        {
            // 45도 비탈면의 노멀 (1, 1, 0)/sqrt(2). y 를 4배로 늘리면 비탈이 가팔라져 노멀은 x 쪽으로 눕는다.
            return Vec("ObjectToWorldNormal((0.7071, 0.7071, 0), 확대 (1, 4, 1))", NormalShading.ObjectToWorldNormal(V(h, h, 0), Scale(1, 4, 1)), 0.970143, 0.242536, 0, 1e-4)
                ?? Vec("ObjectToWorldNormal((0.7071, 0.7071, 0), 확대 (2, 1, 1))", NormalShading.ObjectToWorldNormal(V(h, h, 0), Scale(2, 1, 1)), 0.447214, 0.894427, 0, 1e-4)
                ?? Vec("ObjectToWorldNormal((0, 0.6, 0.8), 확대 (1, 1, 0.25) 후 (9, 9, 9) 이동)", NormalShading.ObjectToWorldNormal(V(0, 0.6, 0.8), Scale(1, 1, 0.25) * Move(9, 9, 9)), 0, 0.184289, 0.982872, 1e-4)
                ?? Vec("ObjectToWorldNormal((0, 1, 0), 확대 (5, 0.1, 5)) [축 방향 노멀은 그대로]", NormalShading.ObjectToWorldNormal(V(0, 1, 0), Scale(5, 0.1, 5)), 0, 1, 0, 1e-4);
        });

        Run("normal-mirrored-scale", () =>
        {
            // 음수 배율(좌우 반전)에서도 노멀은 표면 바깥을 가리켜야 한다
            return Vec("ObjectToWorldNormal((1, 0, 0), 확대 (-1, 1, 1))", NormalShading.ObjectToWorldNormal(V(1, 0, 0), Scale(-1, 1, 1)), -1, 0, 0, 1e-4)
                ?? Vec("ObjectToWorldNormal((0, 1, 0), 확대 (-1, 1, 1))", NormalShading.ObjectToWorldNormal(V(0, 1, 0), Scale(-1, 1, 1)), 0, 1, 0, 1e-4)
                ?? Vec("ObjectToWorldNormal((0.7071, 0.7071, 0), 확대 (-2, 1, 1))", NormalShading.ObjectToWorldNormal(V(h, h, 0), Scale(-2, 1, 1)), -0.447214, 0.894427, 0, 1e-4);
        });

        Run("diffuse-translated-object", () =>
        {
            // 오브젝트가 (10, 0, 0) 으로 옮겨져 있고 광원은 그 바로 위 (10, 5, 0) 에 있다
            return Num("PointLightDiffuse(위치 (0,0,0), 노멀 (0,1,0), (10,0,0) 이동, 광원 (10,5,0))", NormalShading.PointLightDiffuse(V(0, 0, 0), V(0, 1, 0), Move(10, 0, 0), V(10, 5, 0)), 1, 1e-4)
                ?? Num("PointLightDiffuse(위치 (0,0,0), 노멀 (0,1,0), (10,0,0) 이동, 광원 (13,4,0))", NormalShading.PointLightDiffuse(V(0, 0, 0), V(0, 1, 0), Move(10, 0, 0), V(13, 4, 0)), 0.8, 1e-4)
                ?? Num("PointLightDiffuse(위치 (1,0,0), 노멀 (0,1,0), 2배 확대 후 (0,0,-6) 이동, 광원 (2,3,-2))", NormalShading.PointLightDiffuse(V(1, 0, 0), V(0, 1, 0), Scale(2, 2, 2) * Move(0, 0, -6), V(2, 3, -2)), 0.6, 1e-4)
                ?? Num("PointLightDiffuse(위치 (0,0,0), 노멀 (0,1,0), (0,8,0) 이동, 광원 (0,3,0)) [광원이 표면 뒤]", NormalShading.PointLightDiffuse(V(0, 0, 0), V(0, 1, 0), Move(0, 8, 0), V(0, 3, 0)), 0, 1e-4);
        });

        Run("diffuse-identity-and-clamp", () =>
        {
            var id = System.Numerics.Matrix4x4.Identity;
            return Num("PointLightDiffuse(원점, 노멀 (0,1,0), 단위행렬, 광원 (0,2,0))", NormalShading.PointLightDiffuse(V(0, 0, 0), V(0, 1, 0), id, V(0, 2, 0)), 1, 1e-4)
                ?? Num("PointLightDiffuse(원점, 노멀 (0,1,0), 단위행렬, 광원 (3,4,0))", NormalShading.PointLightDiffuse(V(0, 0, 0), V(0, 1, 0), id, V(3, 4, 0)), 0.8, 1e-4)
                ?? Num("PointLightDiffuse(원점, 노멀 (0,1,0), 단위행렬, 광원 (5,0,0)) [스치는 빛]", NormalShading.PointLightDiffuse(V(0, 0, 0), V(0, 1, 0), id, V(5, 0, 0)), 0, 1e-4)
                ?? Num("PointLightDiffuse(원점, 노멀 (0,1,0), 단위행렬, 광원 (0,-4,0)) [뒤쪽 빛]", NormalShading.PointLightDiffuse(V(0, 0, 0), V(0, 1, 0), id, V(0, -4, 0)), 0, 1e-4);
        });

        Run("diffuse-scaled-slope", () =>
        {
            // 확대 (1, 4, 1) 된 45도 비탈면. 월드 노멀은 (0.9701, 0.2425, 0), 표면 점 (1, 1, 0) 은 월드 (1, 4, 0).
            var m = Scale(1, 4, 1);
            return Num("PointLightDiffuse(위치 (1,1,0), 노멀 (0.7071,0.7071,0), 확대 (1,4,1), 광원 (6,4,0))", NormalShading.PointLightDiffuse(V(1, 1, 0), V(h, h, 0), m, V(6, 4, 0)), 0.970143, 1e-4)
                ?? Num("PointLightDiffuse(위치 (1,1,0), 노멀 (0.7071,0.7071,0), 확대 (1,4,1), 광원 (1,9,0))", NormalShading.PointLightDiffuse(V(1, 1, 0), V(h, h, 0), m, V(1, 9, 0)), 0.242536, 1e-4);
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            System.Func<double, double, double> R = (lo, hi) => lo + rng.NextDouble() * (hi - lo);
            for (int i = 0; i < 3000; i++)
            {
                double sx = R(0.3, 3), sy = R(0.3, 3), sz = R(0.3, 3);
                if (rng.Next(4) == 0) sx = -sx;
                var m = Scale(sx, sy, sz) * System.Numerics.Matrix4x4.CreateFromYawPitchRoll((float)R(-3, 3), (float)R(-1.5, 1.5), (float)R(-3, 3)) * Move(R(-20, 20), R(-20, 20), R(-20, 20));
                double[] n = Unit(new double[] { R(-1, 1), R(-1, 1), R(-1, 1) + 1e-3 });
                var nf = V(n[0], n[1], n[2]);
                double[] rn = RefNormal(new double[] { nf.X, nf.Y, nf.Z }, m);
                string e = Vec("ObjectToWorldNormal(" + S(nf) + ", 무작위 model #" + i + ")", NormalShading.ObjectToWorldNormal(nf, m), rn[0], rn[1], rn[2], 2e-3);
                if (e != null) return e;
                var p = V(R(-2, 2), R(-2, 2), R(-2, 2));
                var l = V(R(-40, 40), R(-40, 40), R(-40, 40));
                double exp = RefDiffuse(new double[] { p.X, p.Y, p.Z }, new double[] { nf.X, nf.Y, nf.Z }, m, new double[] { l.X, l.Y, l.Z });
                e = Num("PointLightDiffuse(위치 " + S(p) + ", 노멀 " + S(nf) + ", 무작위 model #" + i + ", 광원 " + S(l) + ")", NormalShading.PointLightDiffuse(p, nf, m, l), exp, 3e-3);
                if (e != null) return e;
                var a = V(n[0], n[1], n[2]); var b = System.Numerics.Vector3.Normalize(V(R(-1, 1), R(0.2, 1), R(-1, 1))); var c = System.Numerics.Vector3.Normalize(a + b + V(0, 0.5, 0));
                double b0 = R(0, 1), b1 = R(0, 1 - b0), b2 = 1 - b0 - b1;
                double[] mix = { a.X * b0 + b.X * b1 + c.X * b2, a.Y * b0 + b.Y * b1 + c.Y * b2, a.Z * b0 + b.Z * b1 + c.Z * b2 };
                if (Dot(mix, mix) < 0.01) continue;
                double[] u = Unit(mix);
                e = Vec("InterpolateNormal (무작위 #" + i + ")", NormalShading.InterpolateNormal(a, b, c, (float)b0, (float)b1, (float)b2), u[0], u[1], u[2], 2e-3);
                if (e != null) return e;
            }
            return null;
        });
    }
